-- Berbers
("en_US", "LOC_TRAIT_CIVILIZATION_CVS_BERBER_UA_XP2_DESCRIPTION", "+50% construction speed towards non-specialty Districts. Aqueduct provides +1 [ICON_FOOD] Food for every adjacenct District, and [ICON_PRODUCION] Production equal to its [ICON_FOOD] Food bonus. Aqueduct buildings are 20% cheaper to purchase. May purchase Aqueduct buildings with [ICON_FAITH] Faith."),
("zh_Hans_CN", "LOC_TRAIT_CIVILIZATION_CVS_BERBER_UA_XP2_DESCRIPTION", "建造非专业化区域时+50%建造速度。水渠每相邻一个区域+1 [ICON_FOOD] 食物，并提供等同于 [ICON_FOOD] 食物加成的 [ICON_PRODUCTION] 生产力。购买水渠建筑的费用降低20%且可以用 [ICON_FAITH] 信仰值购买。"),
("en_US", "LOC_TRAIT_CIVILIZATION_CVS_BERBER_UA_DESCRIPTION", "{LOC_TRAIT_CIVILIZATION_CVS_BERBER_UA_XP2_DESCRIPTION}"),
("zh_Hans_CN", "LOC_TRAIT_CIVILIZATION_CVS_BERBER_UA_DESCRIPTION", "{LOC_TRAIT_CIVILIZATION_CVS_BERBER_UA_XP2_DESCRIPTION}"),
("en_US", "LOC_DISTRICT_FOOD", "+{1_num} [ICON_FOOD] Food from the adjacent {1_Num : plural 1?district; other?districts;}."),
("zh_Hans_CN", "LOC_DISTRICT_FOOD", "+{1_Amount} [ICON_FOOD] 食物来自相邻区域。"),
("en_US", "LOC_TRAIT_LEADER_CVS_DIHYA_UA_DESCRIPTION", "+1 [ICON_MOVEMENT] movement if starting turn in friendly territory. When an enemy unit pillages one of your improvements, all enemy units on or adjacent to that tile with the same owner recieve 30 Damage."),
("zh_Hans_CN", "LOC_TRAIT_LEADER_CVS_DIHYA_UA_DESCRIPTION", "单位在友好领土开始回合+1 [ICON_MOVEMENT] 移动力。当敌人的单位劫掠您的改良时，该文明位于或相邻该单元格的所有单位受到30点伤害。"),
("en_US", "LOC_IMPROVEMENT_CVS_BERBER_UI_DESCRIPTION", "+1 [ICON_HOUSING] Housing, +1 extra [ICON_HOUSING] Housing after researching 'Engineering' Technology, +1 extra [ICON_HOUSING] Housing after researching 'Apprenticeship' Technology. +1 [ICON_FOOD] Food to adjacent resources, extra +1 [ICON_PRODUCTION] Production after researching 'Engineering' Technology. Provides +2 [ICON_FOOD] to adjacent Aqueduct and +2 [ICON_PRODUCTION] Production adjacency bonus to Industial Zone. Cannot be worked. Can only be built on flat lands not adjacent to another Foggara. Can be built on Hills and Floodplains after researching 'Iron Working' Technology."),
("zh_Hans_CN", "LOC_IMPROVEMENT_CVS_BERBER_UI_DESCRIPTION", "+1 [ICON_HOUSING] 住房，解锁“工程”科技后额外+1 [ICON_HOUSING] 住房，解锁“学徒”科技后额外+1 [ICON_HOUSING] 住房。为相邻资源+1 [ICON_FOOD] 食物，解锁“工程”科技后额外+1 [ICON_PRODUCTION] 生产力。为相邻水渠+2 [ICON_FOOD] 食物，为工业区提供+2 [ICON_PRODUCTION] 生产力相邻加成。不能在此单元格工作。只能建造在平坦单元格，且不能相邻另一个柏柏尔井渠。解锁“炼铁术”科技后，允许修建在泛滥平原和丘陵上。"),
("en_US", "LOC_BERBER_UI_FOOD", "+{1_num} [ICON_FOOD] Food from the adjacent Foggara {1_Num : plural 2?improvement; other?improvements;}."),
("zh_Hans_CN", "LOC_BERBER_UI_FOOD", "+{1_Amount} [ICON_FOOD] 食物来自相邻柏柏尔井渠。"),
("en_US", "LOC_BERBER_UI_PRODUCTION", "+{1_num} [ICON_FOOD] Food from the adjacent Foggara {1_Num : plural 2?improvement; other?improvements;}."),
("zh_Hans_CN", "LOC_BERBER_UI_PRODUCTION", "+{1_Amount} [ICON_PRODUCTION] 生产力来自相邻柏柏尔井渠。"),
("en_US", "LOC_UNIT_CVS_BERBER_UU_DESCRIPTION", "Berbers unique unit that replaces the Pikeman. +7 [ICON_STRENGTH] Strength when defending ranged attack, doubled if in friendly territory."),
("zh_Hans_CN", "LOC_UNIT_CVS_BERBER_UU_DESCRIPTION", "柏柏尔特色单位，替代长矛兵。防御远程攻击时+7 [ICON_STRENGTH] 战斗力，位于友好领土时翻倍。"),
("en_US", "LOC_MODIFIER_CVS_BERBER_UU_DEFENDING", "+{1_Amount} Strength when defending ranged attack"),
("zh_Hans_CN", "LOC_MODIFIER_CVS_BERBER_UU_DEFENDING", "防御远程攻击+{1_Amount} 战斗力"),
("en_US", "LOC_MODIFIER_CVS_BERBER_UU_DEFENDING_FRIENDLY", "+{1_Amount} Strength when defending ranged attack in friendly territory."),
("zh_Hans_CN", "LOC_MODIFIER_CVS_BERBER_UU_DEFENDING_FRIENDLY", "位于友好领土防御远程攻击+{1_Amount} 战斗力"),
