-- Swahili
("en_US", "LOC_TRAIT_CIVILIZATION_SUK_CORAL_CONSTRUCTION_DESCRIPTION_XP1", "Districts in coastal Cities receive extra Major adjacency bonus from the City Center, and extra standard bonus from being adjacent to a Harbor. "), --International [ICON_TradeRoute] Trade Routes provide +1 [ICON_Gold] Gold per Fishing Boat in the origin city. +1 [ICON_Production] Production from Sea Features.
("zh_Hans_CN", "LOC_TRAIT_CIVILIZATION_SUK_CORAL_CONSTRUCTION_DESCRIPTION_XP1", "沿海城市中的区域从市中心获得额外大量相邻加成，从港口获得额外标准相邻加成。海洋地貌+1 [ICON_PRODUCTION] 生产力。"),
("en_US", "LOC_TRAIT_LEADER_SUK_HUSUNI_KUBWA_XP2_DESCRIPTION", "Harbours adjacent to a Wonder provide +1 [ICON_TradeRoute] Trade Route Capacity. Patronage of [ICON_GreatPerson] Great People costs 20% less [ICON_GOLD] Gold."), --Patronage of [ICON_GreatPerson] Great People costs 3.33% less [ICON_Gold] Gold for every Wonder built on or adjacent to a Coast tile. The Harbor District provides +1 [ICON_Housing] Housing and +1 [ICON_Culture] Culture, increasing to +3 [ICON_Housing] Housing and +2 [ICON_Culture] Culture if adjacent to a City Center.
("zh_Hans_CN", "LOC_TRAIT_LEADER_SUK_HUSUNI_KUBWA_XP2_DESCRIPTION", "相邻奇观的港口提供+1 [ICON_TradeRoute] 贸易路线，赞助 [ICON_GreatPerson] 伟人消耗的 [ICON_GOLD] 金币减少20%。"), --每座建造在海岸上或与海岸相邻的奇观使赞助 [ICON_GreatPerson] 伟人消耗的 [ICON_GOLD] 金币减少3.33%。港口+1 [ICON_HOUSING] 住房、+1 [ICON_CULTURE] 文化值，若与市中心相邻，则改为+3 [ICON_HOUSING] 住房、+2 [ICON_CULTURE] 文化值。
("en_US", "LOC_BUILDING_SUK_PILLAR_TOMB_XP1_DESCRIPTION", "A building unique to the Swahili. It is cheaper than the Monument which it replaces. +1 [ICON_Culture] Culture, Provides +1 Loyalty per turn in this city. If the city already has maximum Loyalty, also provides an additional +1 [ICON_Culture] Culture. After Calendar is researched, provides an additional +1 [ICON_CULTURE] Culture. International [ICON_TradeRoute] Trade Routes from this city generate +1 [ICON_Gold] Gold, +1 [ICON_Culture] Culture for each of this city’s districts that are within 2 tiles of the City Centre (Capped at +6 [ICON_Gold] )."),
("zh_Hans_CN", "LOC_BUILDING_SUK_PILLAR_TOMB_XP1_DESCRIPTION", "取代纪念碑的斯瓦希里特色建筑。比纪念碑更便宜。提供+1 [ICON_Culture] 文化值。使此城每回合+1忠诚度。若城市忠诚度已达最高，则额外+1 [ICON_Culture] 文化值。研究“历法”科技后，额外+1 [ICON_Culture] 文化值。市中心两个单元格内的每个区域为本城出发的国际 [ICON_TradeRoute] 贸易路线提供+1 [ICON_Culture] 文化值和+1 [ICON_Gold] 金币（上限是+6 [ICON_Culture] 文化值）。"),
("en_US", "LOC_UNIT_SUK_JAHAZI_DESCRIPTION_XP2", "Swahili unique Medieval era support unit. When adjacent to a Jahazi, features on a water tile provide +2 [ICON_Culture] Culture, and Fishing Boats provide +2 [ICON_Gold] Gold. Features on water tiles adjacent to a Jahazi provide +2 [ICON_Tourism] Tourism after researching Conservation. If the Jahazi is in friendly territory, your Naval units within 2 tiles heal +20 HP per turn."),
("zh_Hans_CN", "LOC_UNIT_SUK_JAHAZI_DESCRIPTION_XP2", "斯瓦希里特色中世纪支援单位。相邻的海洋地貌+2 [ICON_Culture] 文化，相邻的渔船+2 [ICON_Gold] 金币。如果在友方领土内，为两个单元格内您的海军单位每回合+20生命值。"),
("en_US", "LOC_UNIT_SWAHILI_DHOW_DESCRIPTION", "Swahili unique unit. Has higher [ICON_STRENGTH] Strength but is more expensive. If 'Industries and Corporations' Mode is enabled, can build a Industry on Sea Luxury."),
("zh_Hans_CN", "LOC_UNIT_SWAHILI_DHOW_DESCRIPTION", "斯瓦希里特色单位。[ICON_STRENGTH] 战斗力更高但更贵。若已开启“行业与公司模式”，可以在海洋奢侈品上建立一个行业。"),
-- Armenia
("en_US", "LOC_TRAIT_CIVILIZATION_CVS_ARMENIA_UA_DESCRIPTION", "Grant a [ICON_GREATPROPHET] Great Prophet when a Vank is built (if you have not received one). +1 [ICON_CULTURE] Culture for every 2 followers of the religion you founded in foreign cities."),
("zh_Hans_CN", "LOC_TRAIT_CIVILIZATION_CVS_ARMENIA_UA_DESCRIPTION", "建成凡克修道院时获得一位 [ICON_GREATPROPHET] 大预言家（如果您尚未获得大预言家）。外国城市每有2个您所创立宗教的信徒便+1 [ICON_CULTURE] 文化值。"),
("en_US", "LOC_TRAIT_LEADER_CVS_TIGRANES_II_UA_DESCRIPTION", "Being [ICON_PROMOTION] Promoted or [ICON_GOLD] Upgraded restores the unit's actions. +1 [ICON_MOVEMENT] Movement for units starting on Hills."),
("zh_Hans_CN", "LOC_TRAIT_LEADER_CVS_TIGRANES_II_UA_DESCRIPTION", "单位晋升和升级会回复已消耗的行动力。单位在丘陵开始回合时+1 [ICON_MOVEMENT] 移动力。"),
("en_US", "LOC_DISTRICT_CVS_ARMENIA_UI_DESCRIPTION", "A district unique to Armenia that replaces the Holy Site. Major adjacency bonus from adjacency Quarry. +1 [ICON_CULTURE] Culture to Quarries in the city."),
("zh_Hans_CN", "LOC_DISTRICT_CVS_ARMENIA_UI_DESCRIPTION", "亚美尼亚特色区域，取代圣地。相邻采石场获得大量相邻加成。此城中采石场+1 [ICON_CULTURE] 文化值。"),
("en_US", "LOC_CVS_ARMENIA_UI_STONE_CIRCLES_DESCRIPTION", "+{1_Amount} [ICON_FAITH] Faith from adjacent Quarry {1_Num : plural 2?improvement; other?improvements;}."),
("zh_Hans_CN", "LOC_CVS_ARMENIA_UI_STONE_CIRCLES_DESCRIPTION", "+{1_Amount} [ICON_FAITH] 信仰来自相邻采石场。"),
("en_US", "LOC_UNIT_CVS_ARMENIA_UU_DESCRIPTION", "Armenia unique unit that replaces the Horseman. Ignore [ICON_MOVEMENT] Movement cost from hills. +5 [ICON_STRENGTH] Strength when attacking Melee units. May be purchased with [ICON_FAITH] Faith."),
("zh_Hans_CN", "LOC_UNIT_CVS_ARMENIA_UU_DESCRIPTION", "亚美尼亚特色单位，取代骑手。忽略丘陵带来的 [ICON_MOVEMENT] 移动力消耗。攻击近战单位时+5 [ICON_STRENGTH]战斗力。可以用 [ICON_FAITH] 信仰值购买。"),
("en_US", "LOC_UNIT_ARMENIA_APOSTLE_DESCRIPTION", "Armenia unique unit that replaces the Apostle. Unlocked with 'Drama and Poetry' Civic, and can be purchased in cities with a Shrine. Increase 500 Religion pressure in cities within 6 tiles when killed."),
("zh_Hans_CN", "LOC_UNIT_ARMENIA_APOSTLE_DESCRIPTION", "亚美尼亚特色单位，取代使徒。由“戏剧与诗歌”市政解锁，需要神社便可以购买。被击杀时向周围6个单元格内的城市施加500宗教压力。"),
-- Malaysia
("en_US", "LOC_TRAIT_CIVILIZATION_CVS_MALAYSIA_UA_DESCRIPTION", "Coast and Lake tiles provide standard adjacency bonus for Commercial Hubs. Gain 1 [ICON_ENVOY] Envoy when you recuit a [ICON_GREATMERCHANT] Great Merchant. +1 [ICON_ENVOY] Envoys awarded for completing City-State Quests if another Civilization is its Suzerain."),
("zh_Hans_CN", "LOC_TRAIT_CIVILIZATION_CVS_MALAYSIA_UA_DESCRIPTION", "海岸和湖泊单元格可为商业中心提供标准相邻加成。每招募一个 [ICON_GREATMERCHANT] 大商人时+1 [ICON_ENVOY] 使者。首次通往城邦的[ICON_TRADEROUTE] 贸易路线将向该城邦派遣1位 [ICON_ENVOY] 使者。"),
("en_US", "LOC_DISTRICT_CVS_MALAYSIA_UI_DESCRIPTION", "Malaysia Unique District that replaces the Harbor. Citizens working in this district also yield [ICON_GREATMERCHANT] Great Merchant points. International trade routes from this City provide +1 [ICON_GOLD] Gold for each Fishing Boat owned by this City.[NEWLINE]Removes the [ICON_MOVEMENT] Movement penalty for embarking and disembarking to and from this tile. Must be built on Coast or Lake Terrain adjacent to land. +2 [ICON_HOUSING] Housing if this city is adjacent to a Coast or a Lake. Fishing Boats provide +1 [ICON_FOOD] Food in this city. +10% [ICON_PRODUCTION] production towards all naval units."),
("zh_Hans_CN", "LOC_DISTRICT_CVS_MALAYSIA_UI_DESCRIPTION", "马来西亚特色区域，取代港口。专家产出额外的 [ICON_GREATMERCHANT] 大商人点数。本城拥有的每个渔船为从该城出发的国际商路+1 [ICON_GOLD] 金币。[NEWLINE]取消从该单元格上下船的 [ICON_MOVEMENT] 移动力消耗。必须修建在和陆地相邻的海岸或湖泊单元格上。如此城与海岸或湖边相邻，则+2 [ICON_HOUSING] 住房。为本城的渔船 +1 [ICON_FOOD] 食物。建造海军单位加速10%。"),
("en_US", "LOC_UNIT_CVS_MALAYSIA_UU_DESCRIPTION", "Malaysia Unique Unit that replaces the Caravel. Stronger. Combat victories heal 30 [ICON_Damaged] Health and provide 20 [ICON_GREATMERCHANT] Great Merchant Points."),
("zh_Hans_CN", "LOC_UNIT_CVS_MALAYSIA_UU_DESCRIPTION", "马来西亚特色单位，取代轻快帆船, 比轻快帆船战斗力更强，每次击杀敌方单位会恢复30 [ICON_Damaged] 生命值，击杀单位后将获得20 [ICON_GREATMERCHANT] 大商人点数。"),
("en_US", "LOC_TRAIT_LEADER_CVS_ISKANDAR_UA_DESCRIPTION", "Cities within 3 tiles of Coast or Lake gain +1 [ICON_CITIZEN] Population and +1 [ICON_AMENITIES] Amenity."),
("zh_Hans_CN", "LOC_TRAIT_LEADER_CVS_ISKANDAR_UA_DESCRIPTION", "建立在海岸或者湖泊3个单元格内的城市+1 [ICON_CITIZEN] 人口、+1 [ICON_AMENITIES] 宜居度。"),
("en_US", "LOC_TRAIT_LEADER_CVS_TUN_PERAK_UA_DESCRIPTION", "In [ICON_GLORY_GOLDEN_AGE] Golden Age, [ICON_CITIZEN] citizens provides +0.3 [ICON_CULTURE] Culture, units gain +3 [ICON_STRENGTH] Combat Strength. Each Government Plaza and Government Plaza building provides +3 [ICON_PRODUCTION] Production and +2 Influence Points."),
("zh_Hans_CN", "LOC_TRAIT_LEADER_CVS_TUN_PERAK_UA_DESCRIPTION", "处于 [ICON_GLORY_GOLDEN_AGE] 黄金或英雄时代时，每位 [ICON_CITIZEN] 市民+0.3 [ICON_CULTURE] 文化值，所有战斗单位+3 [ICON_STRENGTH] 战斗力。每个市政广场和市政广场建筑+3 [ICON_PRODUCTION] 生产力、+2影响力点数。"),
("en_US", "LOC_UNIT_CVS_TUN_PERAK_UU_DESCRIPTION", "Malaysia Unique Unit that replaces the Swordsman. Stronger, and can ignore Zone of Control. +2 [ICON_MOVEMENT] Movement if embarked."),
("zh_Hans_CN", "LOC_UNIT_CVS_TUN_PERAK_UU_DESCRIPTION", "马来西亚特色单位，取代剑士。具有更高的战斗力，且无视区域控制。如果在海岸和湖泊单元格上开始一个回合，会获得2 [ICON_MOVEMENT] 移动力加成。"),
("en_US", "LOC_DISTRICT_COMMERCIAL_HUB_GOLD", "+{1_num} [ICON_GOLD] Gold from the adjacent Coast and Lake {1_Num : plural 1?tile; other?tiles;}."),
("zh_Hans_CN", "LOC_DISTRICT_COMMERCIAL_HUB_GOLD", "+{1_num} [ICON_GOLD] 金币来自相邻的海岸和湖泊单元格。"),
("en_US", "LOC_TUN_PERAK_COMBAT_PREVIEW_TEXT", "from Kingmaker"),
("zh_Hans_CN", "LOC_TUN_PERAK_COMBAT_PREVIEW_TEXT", "来自造王者"),
("en_US", "LOC_ABILITY_CVS_TUN_PERAK_UU_DESCRIPTION", "Ignores Zone of Control"),
("zh_Hans_CN", "LOC_ABILITY_CVS_TUN_PERAK_UU_DESCRIPTION", "无视区域控制");
insert or replace into LocalizedText (Language, Tag, Text) select
"en_US", "LOC_TRAIT_LEADER_CVS_TUN_PERAK_UA_DESCRIPTION", "In [ICON_GLORY_GOLDEN_AGE] Golden Age, [ICON_CITIZEN] citizens provide +0.3 [ICON_CULTURE] Culture, units gain +3 [ICON_STRENGTH] Combat Strength. Each Government Plaza, Diplomatic Quarter and building in these districts provides +3 [ICON_PRODUCTION] Production and +2 Influence Points."
where exists (select Tag from LocalizedText where Tag = 'LOC_CIVILIZATION_ETHIOPIA_NAME');
insert or replace into LocalizedText (Language, Tag, Text) select
"zh_Hans_CN", "LOC_TRAIT_LEADER_CVS_TUN_PERAK_UA_DESCRIPTION", "处于 [ICON_GLORY_GOLDEN_AGE] 黄金或英雄时代时，每位 [ICON_CITIZEN] 市民+0.3 [ICON_CULTURE] 文化值，所有战斗单位+3 [ICON_STRENGTH] 战斗力。每个市政广场、外交区及这些区域中的建筑+3 [ICON_PRODUCTION] 生产力、+2影响力点数。"
where exists (select Tag from LocalizedText where Tag = 'LOC_CIVILIZATION_ETHIOPIA_NAME');